from pathlib import Path
import json,hashlib
import numpy as np,pandas as pd
from scipy.stats import beta
O=Path(__file__).resolve().parent;x=pd.concat([pd.read_parquet(p) for p in sorted((O/'population_trials').glob('*.parquet'))],ignore_index=True);cases=pd.read_json(O/'private_population_cases.json').sort_values('draw_id');q=x[x.policy=='quantum100'];c=x[x.policy=='classicalEB'];assert len(q)==16384 and not x.duplicated(['draw_id','policy','rep']).any()
means=q.groupby('draw_id').agg(quantum_mean_calls=('calls','mean'),success_rate=('success','mean'),complete_rate=('complete','mean'),ratio_asymptotic=('ratio_asymptotic','mean'));means=means.join(c.groupby('draw_id').agg(classical_mean_calls=('calls','mean'),classical_success_rate=('success','mean')));means['gate_factor']=cases.set_index('draw_id').ratio_v1;means['population']=cases.set_index('draw_id').population;means['ratio_EB']=means.quantum_mean_calls*means.gate_factor/means.classical_mean_calls
Q=q.pivot(index='draw_id',columns='rep',values='calls').to_numpy();C=c.pivot(index='draw_id',columns='rep',values='calls').reindex(range(256)).to_numpy();success=q.pivot(index='draw_id',columns='rep',values='success').to_numpy();factors=means.gate_factor.to_numpy();normal=Q.mean(1)*factors/means.ratio_asymptotic.to_numpy();rng=np.random.default_rng(2026111206);boots=[]
for _ in range(2000):
 idx=rng.integers(0,256,256);reps=rng.integers(0,64,(256,64));qm=np.take_along_axis(Q[idx],reps,axis=1).mean(1);cm=np.take_along_axis(C[idx],rng.integers(0,64,(256,64)),axis=1).mean(1);ra=qm*factors[idx]/normal[idx];rc=qm*factors[idx]/cm;ss=np.take_along_axis(success[idx],reps,axis=1).mean()
 boots.append([ss,np.median(ra),np.mean(ra<1),np.nanmedian(rc),np.nanmean(rc<1)])
bs=np.array(boots);names=['quantum_success','median_ratio_asymptotic','share_below_one_asymptotic','median_ratio_EB','share_below_one_EB'];ci={n:np.quantile(bs[:,i],[.025,.975]).tolist() for i,n in enumerate(names)}
result={'protocol_sha256':hashlib.sha256((O/'AMENDMENT_004.md').read_bytes()).hexdigest(),'selection':json.loads((O/'population_manifest.json').read_text()),'new_quantum_attempts':len(q),'new_quantum_completions':int(q.complete.sum()),'new_quantum_successes':int(q.success.sum()),'new_classical_attempts':len(c),'new_classical_completions':int(c.complete.sum()),'new_classical_successes':int(c.success.sum()),'enumeration_eligible_draws':int(c.draw_id.nunique()),'median_ratio_asymptotic':float(means.ratio_asymptotic.median()),'share_below_one_asymptotic':float((means.ratio_asymptotic<1).mean()),'median_ratio_EB':float(means.ratio_EB.median()),'share_below_one_EB':float((means.ratio_EB<1).mean()),'ci95':ci,'interpretation':'Probability-weighted validation on the fixed archived window, not a new patient cohort or a guarantee on every query; query-mean work ratios; both policies and design fixed before these runs; retrospective post-primary extension.'}
draw_success=x.groupby('draw_id').success.all();k=int(draw_success.sum());n=len(draw_success)
result['all_success_draw_batch_one_sided95_lower']=float(beta.ppf(.05,k,n-k+1)) if k else 0.
result['exact_draw_bound_note']='Post-analysis safeguard. One all-128-outcomes-successful event per independently sampled draw; interval concerns the stated draw-and-seed batch mechanism.'
means.reset_index().to_csv(O/'private_population_query_summary.csv',index=False);(O/'population_validation_summary.json').write_text(json.dumps(result,indent=2));print(json.dumps(result,indent=2))
